<template><view><view class="row-between"><view class="section-title">签到任务</view><button v-if="creator" size="mini" class="mini-primary" @click="create">发布签到</button></view><view v-for="t in tasks" :key="t.id" class="card"><view class="section-title">{{ t.title }}</view><view class="muted">{{ t.description||'无说明' }} · 已签到 {{ t.signedCount }} 人</view><view class="row"><button v-if="creator" size="mini" @click="detail(t.id)">查看详情</button><button v-if="!t.signed" size="mini" class="mini-primary" @click="sign(t.id)">立即签到</button><text v-else class="tag">已签到</text></view></view><view v-if="!tasks.length" class="empty">暂无签到任务</view></view></template>
<script setup lang="ts">import{ref,watch}from'vue';import{api}from'@/services/api';import type{SignTask}from'@/services/types';const props=defineProps<{activityId:number;creator:boolean;refreshKey:number}>(),tasks=ref<SignTask[]>([]);async function load(){tasks.value=await api(`/activities/${props.activityId}/sign-tasks`)}watch(()=>props.refreshKey,load,{immediate:true});const create=()=>uni.navigateTo({url:`/pages/signTask/signTask?id=${props.activityId}`});const detail=(id:number)=>uni.navigateTo({url:`/pages/signTaskDetail/signTaskDetail?taskId=${id}`});const sign=(id:number)=>uni.navigateTo({url:`/pages/signIn/signIn?taskId=${id}`})</script>
